insert into public.questions (id, topic_id, prompt, options, answer_index, explanation, sort_order) values
  ('law-657-section-siniflandirma-mtn3uwhn-74-e0ux', 'law-657-section-siniflandirma', 'İstisnai memurluk kadrolarına atananlar hakkında bu Kanun’un hangi hükümleri uygulanmaz?', '["Malî hükümler","Sosyal haklar","Disiplin hükümleri","Yasaklar","Sınav, atanma, derece yükselmesi ve kademe ilerlemesi"]'::jsonb, 4, 'Doğru cevap: E – Sınav, atanma, derece yükselmesi ve kademe ilerlemesi. Dayanak: Yalnızca yüklenen 657 sayılı Devlet Memurları Kanunu metnindeki ilgili hüküm.', 0),
  ('law-657-section-siniflandirma-mtn3uwhn-75-d9qg', 'law-657-section-siniflandirma', 'İstisnai memurluklara atananlar, bu atama nedeniyle kıdem veya müktesep hak kazanırlar mı?', '["Evet, kazanırlar.","Hayır, bu kadrolar kazanılmış hak teşkil etmez.","Sadece valiler kazanır.","Sadece büyükelçiler kazanır.","5 yıl çalışırlarsa kazanırlar."]'::jsonb, 1, 'Doğru cevap: B – Hayır, bu kadrolar kazanılmış hak teşkil etmez. Dayanak: Yalnızca yüklenen 657 sayılı Devlet Memurları Kanunu metnindeki ilgili hüküm.', 0),
  ('law-657-section-siniflandirma-mtn3uwhn-76-dve5', 'law-657-section-siniflandirma', 'Memurların kurumlar arası nakillerinde, kazanılmış hak derecelerinin altındaki derecelere atanabilmeleri için kadro derecesi ile kazanılmış hak derecesi arasındaki fark en çok kaç derece olabilir?', '["1 derece","2 derece","4 derece","3 derece","Fark gözetilmez"]'::jsonb, 3, 'Doğru cevap: D – 3 derece. Dayanak: Yalnızca yüklenen 657 sayılı Devlet Memurları Kanunu metnindeki ilgili hüküm.', 0),
  ('law-657-section-siniflandirma-mtn3uwhn-77-7mlo', 'law-657-section-siniflandirma', '657 sayılı Kanun’a göre “Derece”, memuriyette neyi ifade eder?', '["Memurun maaş tutarını","Memurun hizmet yılını","Memurun çalıştığı kurumu","Memurun eğitim durumunu","Görevin önemini ve sorumluluğunu (Dikey yükselme)"]'::jsonb, 4, 'Doğru cevap: E – Görevin önemini ve sorumluluğunu (Dikey yükselme). Dayanak: Yalnızca yüklenen 657 sayılı Devlet Memurları Kanunu metnindeki ilgili hüküm.', 0),
  ('law-657-section-siniflandirma-mtn3uwhn-78-dpzy', 'law-657-section-siniflandirma', 'Lise mezunu bir memur, memuriyeti sırasında 4 yıllık fakülte bitirirse durumu nasıl değişir (İntibak)?', '["Sadece maaşı artar.","Sadece kıdem yılı artar.","Öğrenim durumuna göre yükselebileceği derece ve kademeye intibakı yapılır (Emsali gibi değerlendirilir).","Bir defaya mahsus 1 derece verilir.","Hiçbir değişiklik olmaz."]'::jsonb, 2, 'Doğru cevap: C – Öğrenim durumuna göre yükselebileceği derece ve kademeye intibakı yapılır (Emsali gibi değerlendirilir). Dayanak: Yalnızca yüklenen 657 sayılı Devlet Memurları Kanunu metnindeki ilgili hüküm.', 0),
  ('law-657-section-siniflandirma-mtn3uwhn-79-0v6m', 'law-657-section-siniflandirma', 'Memurluktan çıkarma cezası alan bir memur, adli yargıda (mahkemede) beraat ederse memuriyete dönebilir mi?', '["Otomatik olarak döner.","Sadece tazminat alır.","Vali kararı ile döner.","Dönemez, disiplin cezası idari bir işlemdir ve bağımsızdır.","5 yıl sonra döner."]'::jsonb, 3, 'Doğru cevap: D – Dönemez, disiplin cezası idari bir işlemdir ve bağımsızdır. Dayanak: Yalnızca yüklenen 657 sayılı Devlet Memurları Kanunu metnindeki ilgili hüküm.', 0),
  ('law-657-section-siniflandirma-mtn3uwhn-8-8i0h', 'law-657-section-siniflandirma', '657 sayılı Devlet Memurları Kanunu’nun 37 nci maddesine göre, memurların kazanılmış hak aylıklarının kadro şartı aranmaksızın bir üst dereceye yükseltilebilmesi için aşağıdakilerden hangisi gereklidir?', '["Azami yükselebileceği derecenin üçüncü kademesinden aylık almaya hak kazanmış olmak","Son bir yıllık süre içinde herhangi bir disiplin cezası almamış olmak","Son sekiz yıllık süre içinde herhangi bir disiplin cezası almamış olmak","Son beş yıllık süre içinde herhangi bir disiplin cezası almamış olmak","Hiçbiri"]'::jsonb, 2, 'Doğru cevap: C – Son sekiz yıllık süre içinde herhangi bir disiplin cezası almamış olmak. Dayanak: 657 sayılı Devlet Memurları Kanunu, Madde 37.', 0),
  ('law-657-section-siniflandirma-mtn3uwhn-80-moks', 'law-657-section-siniflandirma', 'Disiplin kurulları ve yüksek disiplin kurulları, kendilerine intikal eden dosyaları en geç ne kadar süre içinde karara bağlamak zorundadır?', '["Disiplin kurulu 15 gün, Yüksek disiplin kurulu 3 ay","Her ikisi de 30 gün","Her ikisi de 60 gün","Disiplin kurulu 10 gün, Yüksek disiplin kurulu 2 ay","Disiplin kurulu 30 gün, Yüksek disiplin kurulu 6 ay"]'::jsonb, 4, 'Doğru cevap: E – Disiplin kurulu 30 gün, Yüksek disiplin kurulu 6 ay. Dayanak: Yalnızca yüklenen 657 sayılı Devlet Memurları Kanunu metnindeki ilgili hüküm.', 0),
  ('law-657-section-siniflandirma-mtn3uwhn-81-tj5h', 'law-657-section-siniflandirma', 'Memurların hastalık raporlarını hangi hâllerde, hangi hekimlerin vereceği ne ile belirlenir?', '["Kanunla","Genelgeyle","Yönetmelikle","Başhekimlik talimatıyla","İl Sağlık Müdürlüğü kararıyla"]'::jsonb, 2, 'Doğru cevap: C – Yönetmelikle. Dayanak: Yalnızca yüklenen 657 sayılı Devlet Memurları Kanunu metnindeki ilgili hüküm.', 0),
  ('law-657-section-siniflandirma-mtn3uwhn-82-l99a', 'law-657-section-siniflandirma', 'Genel olarak Devlet memuru olabilmek için........................yaşını tamamlamış olmak gerekir.', '["18","15","16","17","20"]'::jsonb, 0, 'Doğru cevap: A – 18. Dayanak: Yalnızca yüklenen 657 sayılı Devlet Memurları Kanunu metnindeki ilgili hüküm.', 0),
  ('law-657-section-siniflandirma-mtn3uwhn-83-vg83', 'law-657-section-siniflandirma', 'Bir meslek veya sanat okulunu bitirenler, en az........................yaşını doldurmuş ve kazai rüşt kararı almış olmak şartıyla memur olabilirler.', '["14","15","16","17","18"]'::jsonb, 1, 'Doğru cevap: B – 15. Dayanak: Yalnızca yüklenen 657 sayılı Devlet Memurları Kanunu metnindeki ilgili hüküm.', 0),
  ('law-657-section-siniflandirma-mtn3uwhn-84-kqkf', 'law-657-section-siniflandirma', 'Usulüne uygun istifa eden memur,........................ay geçmeden yeniden memuriyete alınamaz.', '["6","3","9","12","24"]'::jsonb, 0, 'Doğru cevap: A – 6. Dayanak: Yalnızca yüklenen 657 sayılı Devlet Memurları Kanunu metnindeki ilgili hüküm.', 0),
  ('law-657-section-siniflandirma-mtn3uwhn-85-mmcc', 'law-657-section-siniflandirma', 'Yerine atananın gelmesini beklemeden (çekilmiş sayılarak) ayrılan memur........................yıl geçmeden yeniden memuriyete alınamaz.', '["3 ay","1","6 ay","2","3"]'::jsonb, 1, 'Doğru cevap: B – 1. Dayanak: Yalnızca yüklenen 657 sayılı Devlet Memurları Kanunu metnindeki ilgili hüküm.', 0),
  ('law-657-section-siniflandirma-mtn3uwhn-86-4ty4', 'law-657-section-siniflandirma', 'Memur olmayan eşi ölen memura en yüksek Devlet memuru aylığı tutarında (1 kat)........................yardımı ödenir.', '["Aile","Doğum","Giyecek","Ölüm","Yiyecek"]'::jsonb, 3, 'Doğru cevap: D – Ölüm. Dayanak: Yalnızca yüklenen 657 sayılı Devlet Memurları Kanunu metnindeki ilgili hüküm.', 0),
  ('law-657-section-siniflandirma-mtn3uwhn-87-3ga4', 'law-657-section-siniflandirma', '657 sayılı Devlet Memurları Kanunu’nun 33. maddesinde düzenlenen konu aşağıdakilerden hangisidir?', '["Yurt dışında görevli memurlardan farklı katsayılı memlekete atananların aylıkları","Kadroların tespiti","Sınıfta kalan çocuklar için burs verilemiyeceği","Mecburi hizmetle ilgili yükümlülükler","İstisnai memurluklar"]'::jsonb, 1, 'Doğru cevap: B. 657 sayılı Devlet Memurları Kanunu’nun 33. maddesi “Kadroların tespiti” konusunu düzenler. Maddeye göre kadrosuz memur çalıştırılamaz. (Değişik ikinci fıkra: 2/7/2018 - KHK-703/182 md.) Kadrolar, Cumhurbaşkanlığı kararnamesinde gösterildiği şekilde düzenlenir.', 0),
  ('law-657-section-siniflandirma-mtn3uwhn-88-9luy', 'law-657-section-siniflandirma', '657 sayılı Devlet Memurları Kanunu’nun 37. maddesinde düzenlenen konu aşağıdakilerden hangisidir?', '["Mahrumiyet yerinden başka yere atanan, ölen veya emekliye ayrılanların burs haklarının devamı","Eğitim çalışmalarının sonuçlarının bildirilmesi","Yükselinebilecek derecenin üstünde bir dereceye yükselme","Toplu eylem ve hareketlerde bulunma yasağı","Silah altına alınma"]'::jsonb, 2, 'Doğru cevap: C. 657 sayılı Devlet Memurları Kanunu’nun 37. maddesi “Yükselinebilecek derecenin üstünde bir dereceye yükselme” konusunu düzenler. Maddeye göre bu kanun hükümlerine göre öğrenim durumları, hizmet sınıfları ve görev unvanları itibariyle azami yükselebilecekleri derecelerin dördüncü kademesinden aylık almaya hak kazanan ve son sekiz yıllık süre içinde herhangi bir disiplin cezası almayanların kazanılmış hak aylıkları kadro şartı aranmaksızın bir üst dereceye yükseltilir.', 0),
  ('law-657-section-siniflandirma-mtn3uwhn-89-bcdy', 'law-657-section-siniflandirma', '657 sayılı Devlet Memurları Kanunu’nun 39. maddesinde düzenlenen konu aşağıdakilerden hangisidir?', '["Koordinasyon ve denetleme","Basına bilgi veya demeç verme","İstisnai memurluklara atananlara bu Kanunun uygulanacak hükümleri","Sınıf dışında kadro ihdas edilemeyeceği","Günün 24 saatinde devamlılık gösteren hizmetlerde çalışma saat ve usulünün tespiti"]'::jsonb, 3, 'Doğru cevap: D. 657 sayılı Devlet Memurları Kanunu’nun 39. maddesi “Sınıf dışında kadro ihdas edilemeyeceği” konusunu düzenler. Maddeye göre bu kanuna tabi kurumlarda sınıflar dışında memurluk kadroları ihdas edilemez.', 0),
  ('law-657-section-siniflandirma-mtn3uwhn-9-9bo9', 'law-657-section-siniflandirma', '657 sayılı Devlet Memurları Kanunu’nun 36 ncı maddesine göre, aşağıdakilerden hangisi Eğitim ve Öğretim Hizmetleri Sınıfında yer alır?', '["Mühendis","Öğretmen","Avukat","Tabip","Polis"]'::jsonb, 1, 'Doğru cevap: B – Öğretmen. Dayanak: 657 sayılı Devlet Memurları Kanunu, Madde 36/IV.', 0),
  ('law-657-section-siniflandirma-mtn3uwhn-90-16u4', 'law-657-section-siniflandirma', '657 sayılı Devlet Memurları Kanunu’nun 41. maddesinde düzenlenen konu aşağıdakilerden hangisidir?', '["Resmî belge, araç ve gereçlerin yetki verilen mahaller dışına çıkarılmaması ve iadesi","Sınav sonuçları","Muvazzaf askerliğini yaptıktan sonra Devlet memurluğuna girenlerin kademe intibakları","Görevden uzaklaştırma tedbirinin kaldırılmasında amirin takdiri","Sınıflandırmada öğrenim unsuru"]'::jsonb, 4, 'Doğru cevap: E. 657 sayılı Devlet Memurları Kanunu’nun 41. maddesi “Sınıflandırmada öğrenim unsuru” konusunu düzenler. Maddeye göre genel olarak ortaokulu bitirenler memur olabilirler.', 0),
  ('law-657-section-siniflandirma-mtn3uwhn-91-c7m2', 'law-657-section-siniflandirma', '657 sayılı Devlet Memurları Kanunu’nun 43. maddesinde düzenlenen konu aşağıdakilerden hangisidir?', '["Göstergeler","Atama yapılacak boş kadroların bildirilmesi","Karşılıklı olarak yer değiştirme","Günlük çalışma saatlerinin tesbiti","Kademe ilerlemesinde verilecek aylık"]'::jsonb, 0, 'Doğru cevap: A. 657 sayılı Devlet Memurları Kanunu’nun 43. maddesi “Göstergeler” konusunu düzenler. Maddeye göre bu Kanuna tabi kurumların kadrolarında bulunan personelin aylık ve ek göstergeleri aşağıda gösterildiği şekilde tespit edilir: A) Aylık Göstergesi: Bütün sınıflar itibariyle her derece ve kademenin aylıklarının hesaplanmasına esas teşkil edecek Aylık Gösterge Tablosu aşağıdaki I Numaralı Cetvelde gösterilmiştir.', 0),
  ('law-657-section-siniflandirma-mtn3uwhn-92-qfyf', 'law-657-section-siniflandirma', '657 sayılı Devlet Memurları Kanunu’nun 45. maddesinde düzenlenen konu aşağıdakilerden hangisidir?', '["Bilgilerini artırmak için yabancı memlekete gönderilenlerin hak ve yükümlülükleri","Memurun başka sınıfta ve derecesinin altında bir görevde çalıştırılmıyacağı","Olağanüstü yönetim hallerinde çekilme usulü","Kademe aylığı","Yurt dışında görevli memurlardan farklı katsayılı memlekete atananların aylıkları"]'::jsonb, 1, 'Doğru cevap: B. 657 sayılı Devlet Memurları Kanunu’nun 45. maddesi “Memurun başka sınıfta ve derecesinin altında bir görevde çalıştırılmıyacağı” konusunu düzenler. Maddeye göre hiçbir memur sınıfının dışında ve sınıfının içindeki derecesinin altında bir derecenin görevinde çalıştırılamaz.', 0),
  ('law-657-section-siniflandirma-mtn3uwhn-93-7vtm', 'law-657-section-siniflandirma', '657 sayılı Devlet Memurları Kanunu’na tabi kurumlarda aşağıdakilerden hangisi ihdas edilemez?', '["Sınıflar dışında memurluk kadroları","Kanunda öngörülen sınıflara ait memurluk kadroları","Genel İdare Hizmetleri Sınıfına ait kadrolar","Teknik Hizmetler Sınıfına ait kadrolar","Yardımcı Hizmetler Sınıfına ait kadrolar"]'::jsonb, 0, 'Doğru cevap: A – Bu Kanuna tabi kurumlarda sınıflar dışında memurluk kadroları ihdas edilemez. Dayanak: Madde 39.', 0),
  ('law-657-section-sosyal-haklar-yardimlar-mtn3wel1-0-3nlm', 'law-657-section-sosyal-haklar-yardimlar', '657 sayılı Devlet Memurları Kanunu’nun 208 inci maddesine göre, Devlet memurunun ölümü hâlinde ölüm yardımı ödeneği en yüksek Devlet memuru aylığının kaç katıdır?', '["1/2 katı","1 katı","3 katı","4 katı","2 katı"]'::jsonb, 4, 'Doğru cevap: E – 2 katı. Dayanak: 657 sayılı Devlet Memurları Kanunu, Madde 208.', 0),
  ('law-657-section-sosyal-haklar-yardimlar-mtn3wel1-1-3gbf', 'law-657-section-sosyal-haklar-yardimlar', '657 sayılı Devlet Memurları Kanunu’nun 208 inci maddesine göre, memur olmayan eşi veya aile yardımı ödeneğine müstahak çocuğu ölen memura ne kadar ölüm yardımı ödeneği verilir?', '["En yüksek Devlet memuru aylığının yarısı","En yüksek Devlet memuru aylığının iki katı","En yüksek Devlet memuru aylığı tutarında","Üç katı","Dört katı"]'::jsonb, 2, 'Doğru cevap: C – En yüksek Devlet memuru aylığı tutarında. Dayanak: 657 sayılı Devlet Memurları Kanunu, Madde 208.', 0),
  ('law-657-section-sosyal-haklar-yardimlar-mtn3wel1-10-c3bn', 'law-657-section-sosyal-haklar-yardimlar', '657 sayılı Devlet Memurları Kanunu’na göre Devlet memuruna verilen aile yardımı ödeneği ile ilgili aşağıdaki ifadelerin hangisi yanlıştır?', '["Aile yardımı ödeneği, memurun hiçbir menfaat karşılığı çalışmayan veya herhangi bir sosyal güvenlik kuruluşundan aylık almayan eşi için verilir.","25 yaşını dolduran çocuklar yükseköğrenimlerine devam ettikleri sürece aile yardımı ödeneğinden yararlanmaya devam eder.","Aile yardımı ödeneği, Devlet memurunun geçimini sağladığı üvey çocukları için de verilir.","Devletçe okutulan veya burs alan çocuklar için aile yardımı ödeneği verilmez.","Hiçbiri"]'::jsonb, 1, 'Doğru cevap: B – 25 yaşını dolduran çocuklar yükseköğrenimlerine devam ettikleri sürece aile yardımı ödeneğinden yararlanmaya devam eder. Dayanak: 657 sayılı Devlet Memurları Kanunu, Madde 202-206.', 0),
  ('law-657-section-sosyal-haklar-yardimlar-mtn3wel1-11-nmhg', 'law-657-section-sosyal-haklar-yardimlar', '657 sayılı Kanun“un 206. maddesine göre, aşağıdaki hâllerden hangisinde çocuklar için verilen “Aile Yardımı Ödeneği” kesilmez?', '["25 yaşını bitirdiği halde çalışamayacak derecede malullüğünün resmî sağlık kurulu raporuyla tespit edilmesi","Çocuğun evlenmesi","Çocuğun 25 yaşını doldurması (kız/erkek ayrımı olmaksızın)","Çocuğun kendi hesabına ticaret yapmaya başlaması","Çocuğun burs alması veya Devletçe okutulması"]'::jsonb, 0, 'Doğru cevap: A – 25 yaşını bitirdiği halde çalışamayacak derecede malullüğünün resmî sağlık kurulu raporuyla tespit edilmesi. Dayanak: 657 sayılı Devlet Memurları Kanunu, Madde 202-206.', 0),
  ('law-657-section-sosyal-haklar-yardimlar-mtn3wel1-12-p5bz', 'law-657-section-sosyal-haklar-yardimlar', 'Memur olmayan eşi veya aile yardımı ödeneğine müstahak çocuğu ölen bir Devlet memuruna, “Ölüm Yardımı Ödeneği’ olarak ne kadar ödeme yapılır?', '["En yüksek Devlet memuru aylığının (ek gösterge dahil) iki katı tutarında","En yüksek Devlet memuru aylığı (ek gösterge dahil) tutarında","Memurun kendi aylığının iki katı tutarında","Net asgari ücret tutarında","Cenaze giderleri kadar"]'::jsonb, 1, 'Doğru cevap: B – En yüksek Devlet memuru aylığı (ek gösterge dahil) tutarında. Dayanak: 657 sayılı Devlet Memurları Kanunu, Madde 202-206.', 0),
  ('law-657-section-sosyal-haklar-yardimlar-mtn3wel1-13-qs7v', 'law-657-section-sosyal-haklar-yardimlar', '657 sayılı Kanun“un 203. maddesine göre, ”Aile Yardımı Ödeneği’ ile ilgili aşağıdaki ifadelerden hangisi doğrudur?', '["Aile yardımı ödeneği, memurun maaşıyla birlikte haczedilebilir.","Aile yardımı ödeneği, hiçbir vergi ve kesintiye tabi tutulmaksızın ödenir ve borç için haczedilemez.","Aile yardımı ödeneğinden sadece damga vergisi kesilir.","Aile yardımı ödeneği, memurun isteği üzerine eşine ödenir.","Aile yardımı ödeneği emeklilik keseneğine dahildir."]'::jsonb, 1, 'Doğru cevap: B – Aile yardımı ödeneği, hiçbir vergi ve kesintiye tabi tutulmaksızın ödenir ve borç için haczedilemez. Dayanak: 657 sayılı Devlet Memurları Kanunu, Madde 202-206.', 0),
  ('law-657-section-sosyal-haklar-yardimlar-mtn3wel1-14-28qf', 'law-657-section-sosyal-haklar-yardimlar', 'Aşağıdakilerderi hangisi 657. sayılı Kanun“da belirtilen ”Sosyal Haklar ve Yardımlar’ kapsamında yer almaz?', '["Emeklilik Hakları","Lojman Tazminatı","Cenaze Giderleri","Aile Yârdımı Ödeneği","Ölüm Yardımı Ödeneği"]'::jsonb, 1, 'Doğru cevap: B – Lojman Tazminatı. Dayanak: 657 sayılı Devlet Memurları Kanunu, Madde 187-212 (Sosyal Haklar ve Yardımlar).', 0),
  ('law-657-section-sosyal-haklar-yardimlar-mtn3wel1-15-bqsk', 'law-657-section-sosyal-haklar-yardimlar', '657 sayılı Devlet Memurları Kanunu’na göre mahrumiyet yerlerinde çalışan Devlet memurları görev yerlerinde çocuğunun girmesi gereken orta dereceli okul bulunmadığı takdirde, çocuklarını yatılı okullarda okutmak isterlerse, pansiyon ücretlerinden yüzde kaç oranında indirim uygulanır?', '["Yüzde 50","Yüzde 10","Yüzde 25","Yüzde 40","Yüzde 60"]'::jsonb, 0, 'Doğru cevap: A – Yüzde 50. Dayanak: 657 sayılı Devlet Memurları Kanunu, Madde 199.', 0),
  ('law-657-section-sosyal-haklar-yardimlar-mtn3wel1-16-rkqh', 'law-657-section-sosyal-haklar-yardimlar', '657 sayılı Devlet Memurları Kanunu’na göre aşağıdakilerden hangisi devlet memurlarına verilecek yardımlardan değildir?', '["Tedavi yardımı","Eğitim yardımı","Giyecek yardımı","Yiyecek yardımı","Ölüm yardımı"]'::jsonb, 1, 'Doğru cevap: B – Eğitim yardımı. Dayanak: Yalnızca yüklenen 657 sayılı Devlet Memurları Kanunu metnindeki ilgili hüküm.', 0),
  ('law-657-section-sosyal-haklar-yardimlar-mtn3wel1-17-i3if', 'law-657-section-sosyal-haklar-yardimlar', '657 sayılı Devlet Memurları Kanunu’na göre devlet memurlarından yurt dışında sürekli görevle çalışanlardan aşağıdaki yakınlarından hangisinin ölümü hâlinde cenaze masrafları kurumlarınca karşılanmaz?', '["Eşi","Çocuğu","Babası","Annesi","Kardeşi"]'::jsonb, 4, 'Doğru cevap: E – Kardeşi. Dayanak: 657 sayılı Devlet Memurları Kanunu, Madde 210.', 0),
  ('law-657-section-sosyal-haklar-yardimlar-mtn3wel1-18-grrc', 'law-657-section-sosyal-haklar-yardimlar', 'Devlet memurunun ölümü hâlinde cenaze giderleri, (cenazenin başka yere nakli dahil) kim ya da hangi kurum tarafından ödenir?', '["Özel İdare tarafından","Belediyelerce","Valiliklerce","Kurumlarınca","Hiçbiri"]'::jsonb, 3, 'Doğru cevap: D – Kurumlarınca. Dayanak: 657 sayılı Devlet Memurları Kanunu, Madde 210.', 0),
  ('law-657-section-sosyal-haklar-yardimlar-mtn3wel1-19-7wce', 'law-657-section-sosyal-haklar-yardimlar', '657 sayılı Devlet Memurları Kanunu’na göre aşağıdakilerden hangisi memurların sosyal haklar ve yardımlarından değildir?', '["Yeniden işe alıştırma","Öğrenim bursları ve yurtları","Fazla çalışma ücreti","Ölüm yardımı ödeneği","Aile yardımı ödeneği"]'::jsonb, 2, 'Doğru cevap: C – Fazla çalışma ücreti. Dayanak: 657 sayılı Devlet Memurları Kanunu, Madde 187-212.', 0),
  ('law-657-section-sosyal-haklar-yardimlar-mtn3wel1-2-435q', 'law-657-section-sosyal-haklar-yardimlar', '657 sayılı Devlet Memurları Kanunu’na göre aşağıdaki bilgilerden hangisi yanlıştır?', '["Sürekli görevle yurt dışına gönderilen Devlet memurları, geçici görevle en çok 1 ay süreyle merkeze çağrılabilir.","Gerekli hâllerde malî yılın ikinci yarısı için, genel bütçe kanunu ile tespit edilen katsayıları Cumhurbaşkanı değiştirmeye yetkilidir.","Görevde tutulmasında veya belli yerlerde istihdam edilmesinde güçlük bulunan elemanlara, Eleman teminindeki güçlük zammı ödenir.","Hesaplarını, görevi devralanlara devir zorunluluğu bulunan saymanların devir süresi 5 gündür.","Devlet memurlarının hangi hâllerde yiyecek yardımından ne şekilde faydalanacakları ve bu yardımın uygulanması ile ilgili esaslar Maliye Bakanlığı ile Başbakanlık Devlet Personel Başkanlığının birlikte hazırlayacakları bir yönetmelik ile tespit olunur."]'::jsonb, 3, 'Doğru cevap: D – Hesaplarını, görevi devralanlara devir zorunluluğu bulunan saymanların devir süresi 5 gündür. Dayanak: Yalnızca yüklenen 657 sayılı Devlet Memurları Kanunu metnindeki ilgili hüküm.', 0),
  ('law-657-section-sosyal-haklar-yardimlar-mtn3wel1-20-ikxi', 'law-657-section-sosyal-haklar-yardimlar', '657 sayılı Devlet Memurları Kanunu’na göre aşağıdaki bilgilerden hangisi yanlıştır?', '["Aile yardımı ödeneği memurun şartları taşıyan çocukları için verilebilir.","Yıl içinde ödüllendirilen personel sayısı kurumlarınca izleyen yılın Ocak ayı sonuna kadar Devlet Personel Başkanlığına bildirilir.","Devlet memurunun ölümü hâlinde en yüksek Devlet memuru aylığının iki katı tutarında ölüm yardımı ödeneği verilir.","Devletçe okutulan ve burs alan çocuklar için aile yardımı ödeneği verilir.","Devlet memurları her durumda Devletin menfaatlerini korumak mecburiyetindedirler."]'::jsonb, 3, 'Doğru cevap: D – Devletçe okutulan veya burs alan çocuklar için aile yardımı ödeneği verilmez. Dayanak: 657 sayılı Devlet Memurları Kanunu, Madde 206.', 0),
  ('law-657-section-sosyal-haklar-yardimlar-mtn3wel1-21-64ua', 'law-657-section-sosyal-haklar-yardimlar', 'Devlet Memurlarından T. C. Emekli Sandığına tabi hizmeti........................ve daha fazla olanlara, istekleri üzerine Toplu Konut Fonundan özel şartlarla ve öncelikle konut kredisi verilebilir. 657 Devlet Memurları Kanunu’na göre, yukarıda boş bırakılan alana aşağıdakilerden hangisi gelirse ifade doğru olur?', '["10 yıl","8 yıl","5 yıl","3 yıl","1 yıl"]'::jsonb, 0, 'Doğru cevap: A – 10 yıl. Dayanak: Yalnızca yüklenen 657 sayılı Devlet Memurları Kanunu metnindeki ilgili hüküm.', 0),
  ('law-657-section-sosyal-haklar-yardimlar-mtn3wel1-22-ufhe', 'law-657-section-sosyal-haklar-yardimlar', '657 sayılı Devlet Memurları Kanunu’na göre, memurun çocuklarından her birine hangi gösterge rakamının aylık katsayısı ile çarpılması sonucu elde edilecek miktar üzerinden aile yardım ödeneği ödenir?', '["250","100","150","200","300"]'::jsonb, 0, 'Doğru cevap: A – 250. Dayanak: Yalnızca yüklenen 657 sayılı Devlet Memurları Kanunu metnindeki ilgili hüküm.', 0),
  ('law-657-section-sosyal-haklar-yardimlar-mtn3wel1-23-p860', 'law-657-section-sosyal-haklar-yardimlar', '657 sayılı Devlet Memurları Kanunu’na göre istisnai durumlar hariç en geç kaç yaşını doldurmuş çocuklar için aile yardımı verilmez?', '["18","25","20","21","23"]'::jsonb, 1, 'Doğru cevap: B – 25. Dayanak: 657 sayılı Devlet Memurları Kanunu, Madde 202-206.', 0),
  ('law-657-section-sosyal-haklar-yardimlar-mtn3wel1-24-hppa', 'law-657-section-sosyal-haklar-yardimlar', '657 sayılı Devlet Memurları Kanunu’na göre mahrumiyet yerlerinde çalışan Devlet memurları görev yerlerinde çocuğunun girmesi gereken orta dereceli okul bulunmadığı takdirde, bu dereceli okullarda okuma hakkını kazanmış bulunan çocuklarını yatılı okullarda okutmak isterlerse faydalanacakları pansiyon ücret indirimi çocuklarının her biri için her yıl tespit olunan pansiyon ücretlerinden en azının % kaçı oranındadır?', '["50","7","15","20","75"]'::jsonb, 0, 'Doğru cevap: A – 50. Dayanak: Yalnızca yüklenen 657 sayılı Devlet Memurları Kanunu metnindeki ilgili hüküm.', 0),
  ('law-657-section-sosyal-haklar-yardimlar-mtn3wel1-25-vtg9', 'law-657-section-sosyal-haklar-yardimlar', '657 sayılı Devlet Memurları Kanunu’na göre, devlet Memurları için lüzum ve ihtiyaç görülen yerlerde çocuk bakımevi ve sosyal tesislerin kuruluş ve işletme esas ve usulleri hangi kurumların birlikte hazırlanacak genel yönetmelikle belirlenir?', '["Devlet Personel Başkanlığı, Maliye ve Millî Eğitim Bakanlığı","Devlet Personel Başkanlığı, İçişleri ve Ticaret Bakanlığı","Devlet Personel Başkanlığı, T. C. Hazine ve Maliye Bakanlığı ve İçişleri Bakanlığı","Devlet Personel Başkanlığı ve İçişleri Bakanlığı","Devlet Personel Başkanlığı ile Maliye ve Gümrük Bakanlığı"]'::jsonb, 4, 'Doğru cevap: E – Devlet Personel Başkanlığı ile Maliye ve Gümrük Bakanlığı. Dayanak: 657 sayılı Devlet Memurları Kanunu, Madde 191.', 0),
  ('law-657-section-sosyal-haklar-yardimlar-mtn3wel1-26-ug76', 'law-657-section-sosyal-haklar-yardimlar', 'Çocuk ve Aile yardımı ile ilgili aşağıda verilenlerden hangisi doğrudur?', '["Devletçe okutulan çocuklarda aile yardımı yapılır.","Burs alan çocuklara aile ve çocuk yardımı yapılır.","25 yaşını bitirdiği halde evlenmemiş kız çocuklarına süresiz olarak aile ve çocuk yardımı yapılır.","Evlenen çocuklara aile ve çocuk yardımı yapılır.","Öğrenim yapmakta iken tatil devresinde çalışanlara burs ödenmez."]'::jsonb, 2, 'Doğru cevap: C – 25 yaşını bitirdiği halde evlenmemiş kız çocuklarına süresiz olarak aile ve çocuk yardımı yapılır. Dayanak: 657 sayılı Devlet Memurları Kanunu, Madde 202-206.', 0),
  ('law-657-section-sosyal-haklar-yardimlar-mtn3wel1-27-78tc', 'law-657-section-sosyal-haklar-yardimlar', 'Çocuk ve Aile yardımı ile ilgili aşağıdaki seçeneklerden/şıklardan hangisi yanlıştır?', '["Devlet memurunun, geçimini sağladığı üvey çocukları için de bu ödenek verilir.","25 yaşını dolduran erkek çocuklara aile ve çocuk yardımı yapılmaz.","Burs alan çocuklara aile ve çocuk yardımı yapılır.","Memur, eş için ödenen aile yardımı ödeneğine evlendiği; çocuk için ödenen yardıma da çocuğunun doğduğu tarihi takip eden ay başından itibaren hak kazanır.","Aile yardımı ödenekleri hiçbir vergi ve kesintiye tabi tutulmaksızın ödenir ve borç için haczedilemez."]'::jsonb, 2, 'Doğru cevap: C – Burs alan çocuklara aile ve çocuk yardımı yapılır. Dayanak: 657 sayılı Devlet Memurları Kanunu, Madde 202-206.', 0),
  ('law-657-section-sosyal-haklar-yardimlar-mtn3wel1-28-wac7', 'law-657-section-sosyal-haklar-yardimlar', 'Aşağıdakilerden hangisi memurlara ödenen sosyal hak ve yardımlardan biri değildir?', '["Aile yardımı ödeneği","Yiyecek yardımı","Makam tazminatı","Ölüm yardımı ödeneği","Giyecek yardımı"]'::jsonb, 2, 'Doğru cevap: C – Makam tazminatı. Dayanak: 657 sayılı Devlet Memurları Kanunu, Madde 187-212.', 0),
  ('law-657-section-sosyal-haklar-yardimlar-mtn3wel1-29-1jwv', 'law-657-section-sosyal-haklar-yardimlar', 'Evli bulunan Devlet memurlarına aile yardımı ödeneği verilir. Bu yardım, çocuklardan her biri için de ödenir. Hangi yaş grubunda yer alan çocuklar için bu yardım bir kat artırımlı ödenir?', '["0 – 3 yaş","7 – 12 yaş","0 – 18 yaş","0-6 yaş","12 – 18 yaş"]'::jsonb, 3, 'Doğru cevap: D – 0-6 yaş. Dayanak: 657 sayılı Devlet Memurları Kanunu, Madde 202-206.', 0),
  ('law-657-section-sosyal-haklar-yardimlar-mtn3wel1-3-pqq9', 'law-657-section-sosyal-haklar-yardimlar', 'I. Burs alan veya Devletçe okutulan çocuklar II. Evlenen çocuklar III. 25 yaşını dolduran çocuklar 657 sayılı Devlet Memurları Kanunu’na göre yukarıdakilerden hangileri için çocuk yardımı ödeneği verilmez?', '["I ve II","I ve III","II ve III","Yalnız IV","I, II ve III"]'::jsonb, 4, 'Doğru cevap: E – I, II ve III. Dayanak: 657 sayılı Devlet Memurları Kanunu, Madde 202-206.', 0),
  ('law-657-section-sosyal-haklar-yardimlar-mtn3wel1-30-4bcb', 'law-657-section-sosyal-haklar-yardimlar', 'Aşağıdaki hâllerden hangisinde çocuklar için aile yardımı ödeneği kesilmez?', '["Evlenen çocuklar","25 yaşını dolduran çocuklar (Kız çocukları ve malul olanlar hariç)","Kendileri hesabına ticaret yapan çocuklar","Burs alan veya Devletçe okutulan çocuklar","Yükseköğrenim gören 24 yaşındaki çocuklar"]'::jsonb, 4, 'Doğru cevap: E – Yükseköğrenim gören 24 yaşındaki çocuklar. Dayanak: 657 sayılı Devlet Memurları Kanunu, Madde 202-206.', 0),
  ('law-657-section-sosyal-haklar-yardimlar-mtn3wel1-31-wtmr', 'law-657-section-sosyal-haklar-yardimlar', 'Memur olmayan eşi ölen memura, en yüksek Devlet memuru aylığı (ek gösterge dahil) tutarında ne yardımı yapılır?', '["Ölüm yardımı ödeneği","Cenaze gideri","Aile yardımı","Dul ve yetim aylığı","Tazminat"]'::jsonb, 0, 'Doğru cevap: A – Ölüm yardımı ödeneği. Dayanak: Yalnızca yüklenen 657 sayılı Devlet Memurları Kanunu metnindeki ilgili hüküm.', 0),
  ('law-657-section-sosyal-haklar-yardimlar-mtn3wel1-32-6oyw', 'law-657-section-sosyal-haklar-yardimlar', 'Memurun ölümü hâlinde sağlığında bildirdiği kişiye (yoksa eşine/çocuğuna) en yüksek Devlet memuru aylığının........................katı tutarında ölüm yardımı ödenir.', '["1 (Bir)","1,5","2 (İki)","3","4"]'::jsonb, 2, 'Doğru cevap: C – 2 (İki). Dayanak: 657 sayılı Devlet Memurları Kanunu, Madde 208.', 0),
  ('law-657-section-sosyal-haklar-yardimlar-mtn3wel1-33-9z8d', 'law-657-section-sosyal-haklar-yardimlar', 'Çocuk için verilen aile yardımı ödeneği, çocuk........................yaşını doldurunca kesilir (kız çocukları ve maluller hariç).', '["18","20","21","23","25"]'::jsonb, 4, 'Doğru cevap: E – 25. Dayanak: 657 sayılı Devlet Memurları Kanunu, Madde 202-206.', 0),
  ('law-657-section-sosyal-haklar-yardimlar-mtn3wel1-34-dsos', 'law-657-section-sosyal-haklar-yardimlar', 'Çocuğu ölen memura en yüksek Devlet memuru aylığı tutarında (1 kat)........................yardımı ödeneği verilir.', '["Aile","Ölüm","Doğum","Giyecek","Yiyecek"]'::jsonb, 1, 'Doğru cevap: B – Ölüm. Dayanak: Yalnızca yüklenen 657 sayılı Devlet Memurları Kanunu metnindeki ilgili hüküm.', 0),
  ('law-657-section-sosyal-haklar-yardimlar-mtn3wel1-35-g0o0', 'law-657-section-sosyal-haklar-yardimlar', 'Memurun kendisi ölürse mirasçılarına en yüksek Devlet memuru aylığının........................katı tutarında ölüm yardımı verilir.', '["1 (Bir)","1,5","2 (İki)","3","4"]'::jsonb, 2, 'Doğru cevap: C – 2 (İki). Dayanak: 657 sayılı Devlet Memurları Kanunu, Madde 208.', 0),
  ('law-657-section-sosyal-haklar-yardimlar-mtn3wel1-36-vr2n', 'law-657-section-sosyal-haklar-yardimlar', 'Aile yardımı ödeneği, çocuklar için........................yaşını doldurana kadar verilir (kız çocuklar ve maluller hariç).', '["18","20","21","25","23"]'::jsonb, 3, 'Doğru cevap: D – 25. Dayanak: 657 sayılı Devlet Memurları Kanunu, Madde 202-206.', 0),
  ('law-657-section-sosyal-haklar-yardimlar-mtn3wel1-37-x1eq', 'law-657-section-sosyal-haklar-yardimlar', 'Çocuk 0-6 yaş grubunda ise aile yardımı ödeneği........................kat artırımlı (zamlı) ödenir.', '["Yarım","1,5 (Bir buçuk)","2 (İki)","3 (Üç)","1 (Bir)"]'::jsonb, 4, 'Doğru cevap: E – 1 (Bir). Dayanak: 657 sayılı Devlet Memurları Kanunu, Madde 202-206.', 0),
  ('law-657-section-sosyal-haklar-yardimlar-mtn3wel1-38-4z4d', 'law-657-section-sosyal-haklar-yardimlar', '657 sayılı Devlet Memurları Kanunu’nun 187. maddesinde düzenlenen konu aşağıdakilerden hangisidir?', '["İdari görevlere atanma","İkinci görev yasağı","Ceza kovuşturması sırasında görevden uzaklaştırma","Emeklilik hakları","Vekalet, ikinci görev aylık ve ücretleri ile diğer ödemeler"]'::jsonb, 3, 'Doğru cevap: D. 657 sayılı Devlet Memurları Kanunu’nun 187. maddesi “Emeklilik hakları” konusunu düzenler. Maddeye göre devlet memurlarının emeklilik ve malûllük hallerinde kendilerinin, ölümleri halinde dul ve yetimlerinin sahip bulundukları haklar emeklilik kanunlariyle düzenlenir.', 0),
  ('law-657-section-sosyal-haklar-yardimlar-mtn3wel1-39-vw6l', 'law-657-section-sosyal-haklar-yardimlar', '657 sayılı Devlet Memurları Kanunu’nun 188. maddesinde düzenlenen konu aşağıdakilerden hangisidir?', '["Birleşemiyecek görevler","Yüksek disiplin kurullarının karar usulü, memurun hakkı","Asaleti onaylanan memurların kademe ilerlemeleri","Memurların sosyal tesis ihtiyaçları","Hastalık ve analık sigortası"]'::jsonb, 4, 'Doğru cevap: E. 657 sayılı Devlet Memurları Kanunu’nun 188. maddesi “Hastalık ve analık sigortası” konusunu düzenler. Maddeye göre a) Devlet memurlarının hastalık, analık ve görevden doğan kaza ile mesleki hastalık, B) Devlet memurlarının eşleri ve bakmakla yükümlü oldukları ana, baba ve çocuklarının hastalık ve analık, C) Bir kanuna dayanılarak emekli veya malûllük aylığı alanların (Sosyal Sigortalar Kurumunca uygulanan iş kazaları ile meslek hastalıkları,.', 0),
  ('law-657-section-sosyal-haklar-yardimlar-mtn3wel1-4-8uti', 'law-657-section-sosyal-haklar-yardimlar', '657 sayılı Devlet Memurları Kanunu’nun 206 ncı maddesine göre, istisnalar saklı kalmak üzere çocuk için aile yardımı ödeneği kaç yaşını dolduran çocuklara verilmez?', '["25","18","20","21","23"]'::jsonb, 0, 'Doğru cevap: A – 25. Dayanak: 657 sayılı Devlet Memurları Kanunu, Madde 206.', 0),
  ('law-657-section-sosyal-haklar-yardimlar-mtn3wel1-40-uxuv', 'law-657-section-sosyal-haklar-yardimlar', '657 sayılı Devlet Memurları Kanunu’nun 189. maddesinde düzenlenen konu aşağıdakilerden hangisidir?', '["Yeniden işe alıştırma","Cezai kovuşturma ile disiplin kovuşturmasının bir arada yürütülmesi","Derecelerin ilk ve en yüksek kademe aylıkları","Yolluk giderleri ve gündelikleri","Eğitim birimleri"]'::jsonb, 0, 'Doğru cevap: A. 657 sayılı Devlet Memurları Kanunu’nun 189. maddesi “Yeniden işe alıştırma” konusunu düzenler. Maddeye göre malûllük aylığı bağlanan Devlet memurlarından çalışma gücünün artırılabileceği umulanlar eski sınıflarında veya yeni sınıf veyahut meslekte çalışabilmelerini sağlamak üzere işe alıştırılmaya tabi tutulabilirler.', 0),
  ('law-657-section-sosyal-haklar-yardimlar-mtn3wel1-41-9xcl', 'law-657-section-sosyal-haklar-yardimlar', '657 sayılı Devlet Memurları Kanunu’nun 191. maddesinde düzenlenen konu aşağıdakilerden hangisidir?', '["Memurlara ödenecek aylık tutarları","Memurların sosyal tesis ihtiyaçları","İzin veya geçici görevde iken görev yeri değiştirilen memurların aylıkları","Devlet memurları için konut","Yürürlükten kaldırılan hükümler"]'::jsonb, 1, 'Doğru cevap: B. 657 sayılı Devlet Memurları Kanunu’nun 191. maddesi “Memurların sosyal tesis ihtiyaçları” konusunu düzenler. Maddeye göre devlet Memurları için lüzum ve ihtiyaç görülen yerlerde çocuk bakımevi ve sosyal tesisler kurulabilir.', 0),
  ('law-657-section-sosyal-haklar-yardimlar-mtn3wel1-42-vr93', 'law-657-section-sosyal-haklar-yardimlar', '657 sayılı Devlet Memurları Kanunu’nun 192. maddesinde düzenlenen konu aşağıdakilerden hangisidir?', '["Görev yeri değiştirilenlerden eski görevlerine devamları tebliğ edilenlerin aylıkları","Silah altına alınmazdan önce kadrolarından açıkta bulunanların aylıkları","Devlet memurları için konut kredisi","Devlet memurları eğitimi genel planı","Sınıf dışında kadro ihdas edilemeyeceği"]'::jsonb, 2, 'Doğru cevap: C. 657 sayılı Devlet Memurları Kanunu’nun 192. maddesi “Devlet memurları için konut kredisi” konusunu düzenler. Maddeye göre devlet Memurlarından T. C.', 0),
  ('law-657-section-sosyal-haklar-yardimlar-mtn3wel1-43-9ts2', 'law-657-section-sosyal-haklar-yardimlar', '657 sayılı Devlet Memurları Kanunu’nun 193. maddesinde düzenlenen konu aşağıdakilerden hangisidir?', '["Emeklilik hakları","Giyecek yardımı","Dört istihdam şekli dışında personel çalıştırılamayacağı","Devlet memurları için konut","İdari görevlere atanma"]'::jsonb, 3, 'Doğru cevap: D. 657 sayılı Devlet Memurları Kanunu’nun 193. maddesi “Devlet memurları için konut” konusunu düzenler. Maddeye göre devlet memurlarının lüzum ve zaruret görülen yerlerle kiralık konut ihtiyaçları, Cumhurbaşkanınca onanacak programlar gereğince, genel ve katma bütçelere her yıl konulacak ödeneklerle tesis edilecek fondan karşılanır.275 Bu madde hükmü özel kanunlarla düzenlenir.', 0),
  ('law-657-section-sosyal-haklar-yardimlar-mtn3wel1-44-bow3', 'law-657-section-sosyal-haklar-yardimlar', '657 sayılı Devlet Memurları Kanunu’nun 199. maddesinde düzenlenen konu aşağıdakilerden hangisidir?', '["Yiyecek yardımı","Kamu personeli bilgi sistemi","Memurun başka sınıfta ve derecesinin altında bir görevde çalıştırılmıyacağı","Birleşemiyecek görevler","Öğrenim bursları ve yurtları"]'::jsonb, 4, 'Doğru cevap: E. 657 sayılı Devlet Memurları Kanunu’nun 199. maddesi “Öğrenim bursları ve yurtları” konusunu düzenler. Maddeye göre mahrumiyet yerlerinde çalışan Devlet memurları görev yerlerinde çocuğunun girmesi gereken orta dereceli okul bulunmadığı takdirde, bu dereceli okullarda okuma hakkını kazanmış bulunan çocuklarını yatılı okullarda okutmak isterlerse, pansiyon ücret indiriminden faydalanırlar.', 0),
  ('law-657-section-sosyal-haklar-yardimlar-mtn3wel1-45-m50o', 'law-657-section-sosyal-haklar-yardimlar', '657 sayılı Devlet Memurları Kanunu’nun 200. maddesinde düzenlenen konu aşağıdakilerden hangisidir?', '["Sınıfta kalan çocuklar için burs verilemiyeceği","Türk silahlı kuvvetlerinde çalışan memurlara uygulanmayacak maddeler","Denetimindeki teşebbüsten menfaat sağlama yasağı","Karşılıklı olarak yer değiştirme","Cezai kovuşturma ile disiplin kovuşturmasının bir arada yürütülmesi"]'::jsonb, 0, 'Doğru cevap: A. 657 sayılı Devlet Memurları Kanunu’nun 200. maddesi “Sınıfta kalan çocuklar için burs verilemiyeceği” konusunu düzenler. Maddeye göre pansiyonlarda ücret indiriminden faydalanan memurların çocukları sınıfta kalırlarsa aynı sınıf için ikinci sene bu haktan faydalanamazlar.', 0),
  ('law-657-section-sosyal-haklar-yardimlar-mtn3wel1-46-oqik', 'law-657-section-sosyal-haklar-yardimlar', '657 sayılı Devlet Memurları Kanunu’nun 201. maddesinde düzenlenen konu aşağıdakilerden hangisidir?', '["Kadroların tespiti","Mahrumiyet yerinden başka yere atanan, ölen veya emekliye ayrılanların burs haklarının devamı","İstisnai memurluklara atananlara bu Kanunun uygulanacak hükümleri","Memurluktan çekilenlerin yeniden atanmaları","Memurlara ödenecek aylık tutarları"]'::jsonb, 1, 'Doğru cevap: B. 657 sayılı Devlet Memurları Kanunu’nun 201. maddesi “Mahrumiyet yerinden başka yere atanan, ölen veya emekliye ayrılanların burs haklarının devamı” konusunu düzenler. Maddeye göre öğrenim yılı içinde mahrumiyet yeri ödeneğine tabi olmayan yerlerdeki bir göreve atanan veya ölen veyahut emekliye ayrılan memurların çocukları için yapılan indirim, bulundukları ders yılı sonuna kadarı kendi isteğiyle atananlar için de, atandıkları tarihteki taksit dönemi sonuna kadar devam eder.', 0),
  ('law-657-section-sosyal-haklar-yardimlar-mtn3wel1-47-m3v4', 'law-657-section-sosyal-haklar-yardimlar', '657 sayılı Devlet Memurları Kanunu’nun 203. maddesinde düzenlenen konu aşağıdakilerden hangisidir?', '["İşe başlamama halinde yapılacak işlem","Muvazzaf askerliğini yaptıktan sonra Devlet memurluğuna girenlerin kademe intibakları","Aile yardımı ödeneğinin ödeme usulü","Görevden uzaklaştırma","Görev yeri değiştirilenlerden eski görevlerine devamları tebliğ edilenlerin aylıkları"]'::jsonb, 2, 'Doğru cevap: C. 657 sayılı Devlet Memurları Kanunu’nun 203. maddesi “Aile yardımı ödeneğinin ödeme usulü” konusunu düzenler. Maddeye göre aile yardımı ödeneği Devlet memurlarına her ay aylıklariyle birlikte ödenir.', 0),
  ('law-657-section-sosyal-haklar-yardimlar-mtn3wel1-48-ie5h', 'law-657-section-sosyal-haklar-yardimlar', '657 sayılı Devlet Memurları Kanunu’nun 204. maddesinde düzenlenen konu aşağıdakilerden hangisidir?', '["Seferde veya talim ve manevra için hazarda silah altına alınanların askerlik sürelerinin kademe ve derece intibakları","Disiplin amiri ve disiplin cezaları","Dış memleketler aylık katsayısı","Aile yardımı ödeneğine hak kazanma","Emeklilik hakları"]'::jsonb, 3, 'Doğru cevap: D. 657 sayılı Devlet Memurları Kanunu’nun 204. maddesi “Aile yardımı ödeneğine hak kazanma” konusunu düzenler. Maddeye göre memur, eş için ödenen aile yardımı ödeneğine evlendiği; çocuk için ödenen yardıma da çocuğunun doğduğu tarihi takip eden ay başından itibaren hak kazanır.', 0),
  ('law-657-section-sosyal-haklar-yardimlar-mtn3wel1-49-qofc', 'law-657-section-sosyal-haklar-yardimlar', '657 sayılı Devlet Memurları Kanunu’nun 205. maddesinde düzenlenen konu aşağıdakilerden hangisidir?', '["Karar süresi","Kademe aylığı","Vekalet, ikinci görev aylık ve ücretleri ile diğer ödemeler","Yiyecek yardımı","Aile yardımı ödeneği hakkını kaybetme"]'::jsonb, 4, 'Doğru cevap: E. 657 sayılı Devlet Memurları Kanunu’nun 205. maddesi “Aile yardımı ödeneği hakkını kaybetme” konusunu düzenler. Maddeye göre memur, eş için ödenen aile yardımı ödeneği hakkını eşinden boşanma veya eşinin ölümü, çocuk için ödenen yardım ödeneği hakkını da çocuğun ölümü veya 206 ncı maddedeki hallerin vukuunu takip eden ay başından itibaren kaybeder.', 0),
  ('law-657-section-sosyal-haklar-yardimlar-mtn3wel1-5-8y4x', 'law-657-section-sosyal-haklar-yardimlar', '657 sayılı Devlet Memurları Kanunu’na göre, karı kocanın her ikisi de Devlet memuru ise herhangi bir şekilde menfaat karşılığı çalışmayan çocukları için ödenecek aile yardımı ödeneği ile ilgili aşağıdaki ifadelerden hangisi doğrudur?', '["Bu ödenek yalnızca kadına verilir.","Bu ödenek her iki eşe de ayrı ayrı verilir.","Bu ödenek 1/4 oranında kadına, 3/4 oranında erkeğe verilir.","Bu ödenek yalnızca kocaya verilir.","Bu ödenek her iki eşe de 1/2 oranında ayrı ayrı verilir."]'::jsonb, 3, 'Doğru cevap: D – Bu ödenek yalnızca kocaya verilir. Dayanak: 657 sayılı Devlet Memurları Kanunu, Madde 202-206.', 0),
  ('law-657-section-sosyal-haklar-yardimlar-mtn3wel1-50-tbad', 'law-657-section-sosyal-haklar-yardimlar', '657 sayılı Devlet Memurları Kanunu’nun 210. maddesinde düzenlenen konu aşağıdakilerden hangisidir?', '["Cenaze giderleri","Derece aylığı","Derece değişikliğinde aylığa hak kazanma","Yeniden işe alıştırma","Türk silahlı kuvvetlerinde çalışan memurlara uygulanmayacak maddeler"]'::jsonb, 0, 'Doğru cevap: A. 657 sayılı Devlet Memurları Kanunu’nun 210. maddesi “Cenaze giderleri” konusunu düzenler. Maddeye göre devlet memurlarının ölümü halinde cenaze giderleri (cenazenin başka yere nakil dahil) kurumlarınca ödenir.', 0),
  ('law-657-section-sosyal-haklar-yardimlar-mtn3wel1-51-d7d6', 'law-657-section-sosyal-haklar-yardimlar', '657 sayılı Devlet Memurları Kanunu’nun 211. maddesinde düzenlenen konu aşağıdakilerden hangisidir?', '["Görev yeri değiştirilen memurların aylıkları","Giyecek yardımı","Seferde muvazzaflık hizmeti dışında silah altına alınan memurların aylıklarının ödenmesi","Eğitim birimleri","Kadroların tespiti"]'::jsonb, 1, 'Doğru cevap: B. 657 sayılı Devlet Memurları Kanunu’nun 211. maddesi “Giyecek yardımı” konusunu düzenler. Maddeye göre devlet memurlarından hangilerinin ne şekilde giyecek yardımından faydalanacakları Maliye Bakanlığı ile Başbakanlık Devlet Personel Başkanlığının birlikte hazırlıyacakları bir yönetmelik ile tesbit olunur.', 0),
  ('law-657-section-sosyal-haklar-yardimlar-mtn3wel1-52-5l6n', 'law-657-section-sosyal-haklar-yardimlar', '657 sayılı Devlet Memurları Kanunu’nun 212. maddesinde düzenlenen konu aşağıdakilerden hangisidir?', '["Sefer haline geçişte silah altında bulunan memurların aylıkları","Aile yardımı ödeneğine hak kazanma","Yiyecek yardımı","Yürürlükten kaldırılan hükümler","İşe başlamama halinde yapılacak işlem"]'::jsonb, 2, 'Doğru cevap: C. 657 sayılı Devlet Memurları Kanunu’nun 212. maddesi “Yiyecek yardımı” konusunu düzenler. Maddeye göre devlet memurlarının hangi hallerde yiyecek yardımından ne şekilde faydalanacakları ve bu yardımın uygulanması ile ilgili esaslar Maliye Bakanlığı ile Başbakanlık Devlet Personel Başkanlığının birlikte hazırlıyacakları bir yönetmelik ile tesbit olunur.', 0),
  ('law-657-section-sosyal-haklar-yardimlar-mtn3wel1-6-u9pk', 'law-657-section-sosyal-haklar-yardimlar', 'Aşağıdaki hangi hâllerde Çocuk için aile yardım ödeneği verilemez?', '["Dul memurların çocukları","Devlet memurunun geçimini sağladığı üvey çocuklar için","Burs alan veya Devletçe okutulan çocuklar için","0-6 yaş grubu çocuklar için","Hiçbiri"]'::jsonb, 2, 'Doğru cevap: C – Burs alan veya Devletçe okutulan çocuklar için. Dayanak: 657 sayılı Devlet Memurları Kanunu, Madde 206.', 0),
  ('law-657-section-sosyal-haklar-yardimlar-mtn3wel1-7-0dil', 'law-657-section-sosyal-haklar-yardimlar', '657 sayılı Devlet Memurları Kanunu’na göre, aşağıdakilerden hangisi hiçbir vergi ve kesintiye tabi tutulmaz?', '["Özel hizmet tazminatı","Yabancı dil tazminatı","Yan ödeme","Aile yardımı ödeneği","Hiçbiri"]'::jsonb, 3, 'Doğru cevap: D – Aile yardımı ödeneği. Dayanak: 657 sayılı Devlet Memurları Kanunu, Madde 203.', 0),
  ('law-657-section-sosyal-haklar-yardimlar-mtn3wel1-8-4afn', 'law-657-section-sosyal-haklar-yardimlar', 'Ölüm yardımı ödeneğinin ödenmesinde esas alınan aylık kavramı aşağıdakilerden hangisidir?', '["Memurun kazanılmış hak aylığı","1000 gösterge rakamının memur maaş katsayısı ile çarpımı sonucu bulunan tutar","Aylık ve ek gösterge tutarı","En yüksek Devlet memuru aylığı (ek gösterge dâhil)","Hiçbiri"]'::jsonb, 3, 'Doğru cevap: D – En yüksek Devlet memuru aylığı (ek gösterge dâhil). Dayanak: 657 sayılı Devlet Memurları Kanunu, Madde 208.', 0),
  ('law-657-section-sosyal-haklar-yardimlar-mtn3wel1-9-2q6d', 'law-657-section-sosyal-haklar-yardimlar', 'Çocuk için ödenen aile yardımı ödeneği aşağıdakilerden hangisinde ödenmez?', '["30 yaşında bekar kız çocuğu için","Askeri okulda okuyan çocuk için","24 yaşında erkek çocuk için","Öğrenim yapmakta iken yaz tatilinde çalışan çocuk için","Hiçbiri"]'::jsonb, 1, 'Doğru cevap: B – Askeri okulda okuyan çocuk için. Dayanak: 657 sayılı Devlet Memurları Kanunu, Madde 202-206.', 0),
  ('manual-pool-100', 'law-5018', 'Kapsam, temel ilkeler ve kurumsal çevre düzenlemesine göre malî istatistiklerin hazırlanmasında kamu idarelerinin yöneticileri neyin oluşturulması için gerekli önlemleri alır?', '["Sadece personel sayısının artırılmasının","Uygun kurumsal çevrenin","Sadece bilgisayar altyapısının","Sadece uluslararası kredi derecesinin","Sadece bütçe fazlasının"]'::jsonb, 1, NULL, 4),
